import java.util.*;

class Solution {
    private List<Integer> getSums(int[] arr) {
        List<Integer> sums = new ArrayList<>();
        sums.add(0);
        for (int x : arr) {
            int sz = sums.size();
            for (int i = 0; i < sz; ++i) {
                sums.add(sums.get(i) + x);
            }
        }
        return sums;
    }

    public int minAbsDifference(int[] nums, int goal) {
        int n = nums.length;
        int mid = n / 2;
        int[] leftNums = Arrays.copyOfRange(nums, 0, mid);
        int[] rightNums = Arrays.copyOfRange(nums, mid, n);

        List<Integer> leftSums = getSums(leftNums);
        List<Integer> rightSums = getSums(rightNums);
        Collections.sort(rightSums);

        int ans = Integer.MAX_VALUE;
        int m = rightSums.size();
        for (int s : leftSums) {
            int target = goal - s;
            int idx = Collections.binarySearch(rightSums, target);
            if (idx >= 0) return 0;
            idx = -(idx + 1);
            if (idx < m) {
                ans = Math.min(ans, Math.abs(s + rightSums.get(idx) - goal));
            }
            if (idx > 0) {
                ans = Math.min(ans, Math.abs(s + rightSums.get(idx - 1) - goal));
            }
        }
        return ans;
    }
}

