var minAbsDifference = function(nums, goal) {
    const n = nums.length;
    const mid = Math.floor(n / 2);
    const leftNums = nums.slice(0, mid);
    const rightNums = nums.slice(mid);

    const getSums = (arr) => {
        let sums = [0];
        for (const x of arr) {
            const next = [];
            for (let i = 0; i < sums.length; ++i) {
                next.push(sums[i] + x);
            }
            sums = sums.concat(next);
        }
        return sums;
    };

    const leftSums = getSums(leftNums);
    const rightSums = getSums(rightNums).sort((a, b) => a - b);

    let ans = Infinity;
    const m = rightSums.length;
    for (const s of leftSums) {
        const target = goal - s;
        let low = 0, high = m;
        while (low < high) {
            const midIdx = Math.floor((low + high) / 2);
            if (rightSums[midIdx] < target) low = midIdx + 1;
            else high = midIdx;
        }
        if (low < m) {
            ans = Math.min(ans, Math.abs(s + rightSums[low] - goal));
        }
        if (low > 0) {
            ans = Math.min(ans, Math.abs(s + rightSums[low - 1] - goal));
        }
        if (ans === 0) return 0;
    }
    return ans;
};
